import prisma from '@/lib/prisma'

/** Crée l'édition 14 si la table est vide (db push sans seed SQL). */
export async function ensureDefaultEdition() {
  const existing = await prisma.edition.findFirst({ where: { numero: 14 } })
  if (existing) return existing

  const count = await prisma.edition.count()
  if (count > 0) return null

  return prisma.edition.create({
    data: {
      id: 'seed-edition-14',
      numero: 14,
      titre: 'Édition 2025-2026',
      description: 'Dernière édition — formation en cours à l\'École d\'Évangélisation.',
      estCourante: true,
    },
  })
}

export async function getEditionsForPublic() {
  return prisma.edition.findMany({
    orderBy: { numero: 'desc' },
    select: {
      id: true,
      numero: true,
      titre: true,
      description: true,
      estCourante: true,
    },
  })
}

export async function getCurrentEdition() {
  return prisma.edition.findFirst({
    where: { estCourante: true },
    orderBy: { numero: 'desc' },
    select: {
      id: true,
      numero: true,
      titre: true,
      description: true,
      estCourante: true,
    },
  })
}

export async function getEditionPhotosPublic(editionId: string) {
  return prisma.editionPhoto.findMany({
    where: { editionId, publiee: true },
    orderBy: [{ ordre: 'asc' }, { createdAt: 'asc' }],
    select: {
      id: true,
      imageUrl: true,
      legende: true,
    },
  })
}

export async function getPublishedRapports() {
  return prisma.rapportEcole.findMany({
    where: { publiee: true },
    orderBy: { dateEvenement: 'desc' },
    select: {
      id: true,
      titre: true,
      contenu: true,
      imageUrl: true,
      dateEvenement: true,
      edition: {
        select: { numero: true, titre: true },
      },
    },
  })
}

